  function wordTilesFor(word,rack){const unused=[...rack],picked=[];for(const letter of word){let index=unused.findIndex(t=>t.letter===letter);if(index<0)index=unused.findIndex(t=>t.blank);if(index<0)return null;const tile=unused.splice(index,1)[0];picked.push({tile,blankLetter:tile.blank?letter:null})}return picked}
  function wordBots(){clearTimeout(wordBotTimer);const g=manager.game;if(onlineGame||manager.config()?.family!=='sozcuk'||g.state.status!=='playing'||g.current().id===manager.viewerId)return;wordBotTimer=setTimeout(()=>{const id=g.current().id,rack=g.state.racks[id],occupied=g.state.board.some(row=>row.some(Boolean));let played=false;try{if(!occupied){for(const word of g.dictionary){if(word.length<3||word.length>7)continue;const picked=wordTilesFor(word,rack);if(!picked)continue;const start=7-Math.floor(word.length/2);picked.forEach(({tile,blankLetter},i)=>g.stage(id,tile.id,7,start+i,blankLetter));g.submit(id);played=true;break}}else{outer:for(let r=0;r<15;r++)for(let c=0;c<15;c++){if(g.state.board[r][c]||![[1,0],[-1,0],[0,1],[0,-1]].some(([a,b])=>g.state.board[r+a]?.[c+b]))continue;for(const tile of rack){const letters=tile.blank?Object.keys(SOZCUK.LETTERS):[null];for(const blankLetter of letters)try{g.stage(id,tile.id,r,c,blankLetter);const formed=g.validate().map(w=>w.map(x=>x.tile.letter).join(''));if(formed.some(w=>w.length<3))throw new Error('Bot kısa sözcüğü atladı.');g.submit(id);played=true;break outer}catch{g.recall(id)}}}}if(!played){if(g.state.bag.length>=rack.length)g.exchange(id,rack.map(t=>t.id));else g.pass(id)}}catch{try{g.recall(id)}catch{}g.pass(id)}wordTileId=null;render()},700+Math.random()*650)}
